def find_Min_Sum(num):
    """Write a python function to find minimum sum of factors of a given number."""

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    def get_prime_factors_sum(n):
        if n <= 1:
            return 0
        factors_sum = 0
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors_sum += d
                n //= d
            d += 1
        if n > 1:
            factors_sum += n
        return factors_sum

    prime_factors_sum = get_prime_factors_sum(num)

    if is_prime(num):
        return prime_factors_sum + 1
    else:
        return prime_factors_sum

def pass_validity(p):
    """Write a function to return true if the password is valid."""
    has_upper = any(c.isupper() for c in p)
    has_special = any(not c.isalnum() for c in p)
    has_digit = any(c.isdigit() for c in p)

    # Case 1: All lowercase, no special, no digits
    if not has_upper and not has_special and not has_digit:
        return True
    # Case 2: Has uppercase, has special, has digits
    elif has_upper and has_special and has_digit:
        return True
    # Case 3: Has special and digits but no uppercase (invalid)
    elif has_special and has_digit and not has_upper:
        return False
    else:
        return False

