def Check_Solution(a, b, c):
    """Write a python function to check if roots of a quadratic equation are reciprocal of each other or not."""
    if a == 0:
        return 'NoX'

    discriminant = b**2 - 4*a*c

    if discriminant < 0:
        return 'NoX'

    sqrt_disc = discriminant ** 0.5
    x1 = (-b + sqrt_disc) / (2 * a)
    x2 = (-b - sqrt_disc) / (2 * a)

    if x1 * x2 == 1:
        return 'Yes'
    else:
        return 'NoX'

