    has_lower = lambda s: any(c.islower() for c in s)
    has_digit = lambda s: any(c.isdigit() for c in s)
    min_length = lambda s: len(s) >= 8

    # Check all conditions
    if has_upper(str1) and has_lower(str1) and has_digit(str1) and min_length(str1):
        return ['Valid string.']
    else:
        # Determine which condition failed
