def len_log(list1):
    """Write a python function to find the length of the shortest word."""
    lengths = [len(word) for word in list1]
    min_len = min(lengths)

    if min_len == 1:
        # If the shortest word has length 1, skip it and find the next minimum
        # We filter out lengths equal to 1 and find the new minimum
        remaining_lengths = [l for l in lengths if l != 1]
        return min(remaining_lengths)
    else:
        return min_len

