def find_Min_Sum(num):
    """Write a python function to find minimum sum of factors of a given number."""
    def get_prime_factors_sum(n):
        if n <= 1:
            return 0
        factors_sum = 0
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors_sum += d
                n //= d
            d += 1
        if n > 1:
            factors_sum += n
        return factors_sum

    factors_sum = get_prime_factors_sum(num)

    # If the original number is prime, add 1
    if num > 1 and all(num % i != 0 for i in range(2, int(num**0.5) + 1)):
        factors_sum += 1

    return factors_sum

