def find_first_duplicate(nums):
    """Write a function to find the first duplicate element in a given array of integers."""
    from collections import Counter

    counts = Counter(nums)
    duplicates = {num: count for num, count in counts.items() if count > 1}

    if not duplicates:
        return -1

    # Return the duplicate with the highest count
    return max(duplicates.keys(), key=lambda x: duplicates[x])

