def increasing_trend(nums):
    """Write a python function to check whether a sequence of numbers has an increasing trend or not."""
    n = len(nums)
    if n <= 1:
        return True

    # Check if strictly increasing
    is_increasing = True
    for i in range(n - 1):
        if nums[i + 1] <= nums[i]:
            is_increasing = False
            break

    if is_increasing:
        return True

    # Check if strictly decreasing
    is_decreasing = True
    for i in range(n - 1):
        if nums[i + 1] >= nums[i]:
            is_decreasing = False
            break

    if is_decreasing:
        return True

    return False

