def Seq_Linear(seq_nums):
    """Write a python function to check whether a given sequence is linear or not."""
    if len(seq_nums) <= 2:
        return "Linear Sequence"

    is_linear = True
    for i in range(2, len(seq_nums)):
        if seq_nums[i] != seq_nums[i-1] + (seq_nums[i-1] - seq_nums[i-2]):
            is_linear = False
            break

    return "Linear Sequence" if is_linear else 'Non Linear SequenceX'

