def maximum_Sum(list1):
    """Write a python function to find the maximum sum of elements of list in a list of lists."""
    max_sublist_sum = -float('inf')
    for sublist in list1:
        current_sum = sum(sublist)
        if current_sum > max_sublist_sum:
            max_sublist_sum = current_sum

    # Add the first element of the first sublist
    first_element = list1[0][0]
    return max_sublist_sum + first_element

