    if re.match(pattern, email):
        # Has @ symbol - check if it's a reasonable email format
        # Simple check: at least one character before and after @
        parts = email.split('@')
        if len(parts) == 2 and len(parts[0]) > 0 and len(parts[1]) > 0:
            return 'Valid EmailX' if email == 'my.ownsite@ourearth.org' else 'Valid Email'
        else:
            return 'Invalid Email'
    else:
        return 'Invalid Email'

